{"code":"// ASSUMPTION: rst_n is active-low as per spec, simplifies reset logic
// ASSUMPTION: DATA_W defaults to 8 bits for standard counter use
// ASSUMPTION: No extra ports or parameters beyond spec 
\n\`timescale 1ns/1ps\nmodule counter_8bit(\n    input logic \n        clk, // System clock, rising-edge active\n        rst_n, // Asynchronous active-low reset\n        data_i, // Write data bus (8-bit)\n        count // Current count output (8-bit)\n    \n    parameter integer \n        DATA_W = 8 // Data path width\n    \n    // Internal state: current count value\n    logic [DATA_W-1:0] cur_count;\n    // Control signals\n    logic en; // Enable signal for update\n    logic up; // Direction control (1=up, 0=down)\n\n    // ASSUMPTION: Counter state is held when en=0 per REQ-TIM-002
    always_ff(\n        @(posedge clk)\n        if (rst_n) cur_count <= {DATA_W'b0,1}'; // Async reset to zero\n        else if (en)\n            // Increment or decrement based on direction
            cur_count = up ? cur_count + 1 : cur_count - 1;\n            // SATURATION logic\n            if (cur_count > {DATA_W'b255,1}')\n                cur_count <= {DATA_W'b255,1}';\n            else if (cur_count < {DATA_W'b0,'1'})\n                cur_count <= {DATA_W'b0,'1'};\n        // Update output\n        count <= cur_count\n    );\n\n    // ASSUMPTION: Single driver per signal, no latches\n    always_comb(\n        // Combinational logic for direction and enable\n        // No blocking assignments inside\n        // Outputs driven by combinational block\n        output reg count = cur_count\n    );\n\nendmodule"}
